import { addWeeks } from '../week';
import { Icon } from './icon';
import { WeekPicker } from './week-picker';

@Component({
  selector: 'app-dashboard-filters',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [Icon, WeekPicker],
